const items = [];

for (const item of $input.all()) {
  const data = item.json;
  const organicResults = data.organic_results || [];

  for (const result of organicResults) {
    const link = result.link || '';
    const title = result.title || '';
    const snippet = result.snippet || '';

    // Skip irrelevant results
    if (!link || link.includes('wikipedia') || link.includes('youtube')) continue;

    // Extract domain for company identification
    let domain = '';
    try {
      domain = new URL(link).hostname.replace('www.', '');
    } catch(e) { continue; }

    // Determine company type from snippet/title
    let sectorGuess = 'genel işletme';
    const text = (title + ' ' + snippet).toLowerCase();
    if (text.includes('restoran') || text.includes('kafe') || text.includes('yemek')) sectorGuess = 'restoran/kafe';
    else if (text.includes('mağaza') || text.includes('e-ticaret') || text.includes('satış')) sectorGuess = 'e-ticaret/mağaza';
    else if (text.includes('hukuk') || text.includes('avukat')) sectorGuess = 'hukuk bürosu';
    else if (text.includes('klinik') || text.includes('diş') || text.includes('doktor')) sectorGuess = 'sağlık klinik';
    else if (text.includes('inşaat') || text.includes('emlak')) sectorGuess = 'inşaat/emlak';
    else if (text.includes('otomotiv') || text.includes('araç')) sectorGuess = 'otomotiv';

    items.push({
      json: {
        company_name: title.split('|')[0].split('-')[0].trim(),
        website: link,
        domain: domain,
        sector: sectorGuess,
        snippet: snippet,
        source: 'google_search'
      }
    });
  }
}

return items;

const results = [];

for (const item of $input.all()) {
  const lead = item.json;
  const hunterData = lead.data || {};
  const emails = hunterData.emails || [];

  if (emails.length === 0) continue; // Email bulunamazsa atla

  const topEmail = emails[0];

  results.push({
    json: {
      company_name: lead.company_name || hunterData.organization || 'Sayın Yetkili',
      contact_name: topEmail.first_name ? `${topEmail.first_name} ${topEmail.last_name || ''}`.trim() : '',
      contact_email: topEmail.value,
      contact_title: topEmail.position || '',
      website: lead.website,
      sector: lead.sector,
      snippet: lead.snippet
    }
  });
}

return results;

