const results = [];

for (const item of $input.all()) {
  const aiResponse = item.json.message?.content || item.json.choices?.[0]?.message?.content || '';

  let parsed;
  try {
    // GPT bazen markdown code block içinde döner, temizle
    const cleaned = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch(e) {
    // JSON parse başarısız olursa ham metni kullan
    parsed = {
      subject: 'Bey Digital Media – Dijital Büyüme Fırsatı',
      body: aiResponse
    };
  }

  results.push({
    json: {
      ...item.json,
      email_subject: parsed.subject,
      email_body: parsed.body,
      generated_at: new Date().toISOString()
    }
  });
}

return results;

